<?php use App\Core\Auth; use App\Services\Finance; ?>
<?php if(Auth::can('invoices.write')): ?><div class="toolbar"><p class="muted">Generate invoices individually or review an entire class.</p><a class="button primary" href="<?= e(url('batch',['kind'=>'billing'])) ?>">Generate class invoices →</a></div><?php endif ?>
<?php if(Auth::can('invoices.write')): ?><details class="panel"><summary>＋ Generate an invoice</summary><p class="muted">Charges are selected automatically from the student’s current type, academic year, class and selected term.</p><?php startForm('invoice.create'); selectField('student_id','Student','students'); selectField('term_id','Term','terms'); field('issued_on','Issue date','date',date('Y-m-d')); field('due_on','Due date','date',date('Y-m-d',strtotime('+30 days'))); endForm('Generate invoice'); ?></details><?php endif ?>
<section class="panel"><form method="get" class="filters"><input type="hidden" name="page" value="invoices"><?php selectField('status','Invoice status',['Unpaid','Partially Paid','Paid','Overdue','Cancelled'],$_GET['status']??'',false); selectField('class_id','Class','classes',$_GET['class_id']??'',false); selectField('student_type_id','Student type','student_types',$_GET['student_type_id']??'',false); ?><button class="button">Apply filters</button><a href="<?= e(url('invoices')) ?>">Reset</a></form><div class="table-wrap"><table><thead><tr><th>Invoice / student</th><th>Class / term</th><th>Type</th><th>Due date</th><th class="num">Total</th><th class="num">Paid</th><th class="num">Balance</th><th>Status</th></tr></thead><tbody><?php if(!$rows) emptyRow(8); foreach(array_slice($rows,0,50) as $i): ?><tr><td><a href="<?= e(url('invoice',['id'=>$i['id']])) ?>"><strong><?= e($i['number']) ?></strong></a><small><?= e($i['first_name'].' '.$i['last_name']) ?></small></td><td><?= e($i['class_name']) ?><small><?= e($i['year_name'].' · '.$i['term_name']) ?></small></td><td><?= e($i['type_name']) ?></td><td><?= e($i['due_on']) ?></td><td class="num"><?= money($i['total']) ?></td><td class="num"><?= money($i['paid']) ?></td><td class="num"><strong><?= $i['cancelled_at']?'—':money($i['balance']) ?></strong></td><td><?php badge(Finance::status($i)); ?></td></tr><?php endforeach ?></tbody></table></div><?php pagination(max(1,(int)($_GET['p']??1)),count($rows)>50); ?></section>
